#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_print_number_negative_num_digits_all_nonzero(void) {
    uint8_t N = 5;
    uint8_t number[] = {3, 2, 1, 0, 0};  // Little-endian: represents "00123" -> "123"
    int8_t num_digits_to_print = -1;  // Negative means print all non-zero digits

    // Redirect stdout to a temporary file
    FILE *original_stdout = stdout;
    FILE *temp_file = tmpfile();
    if (temp_file == NULL) {
        TEST_FAIL_MESSAGE("Failed to create temporary file for stdout capture");
        return;
    }
    stdout = temp_file;

    int result = print_number(number, N, num_digits_to_print);

    // Restore stdout
    stdout = original_stdout;

    // Read captured output
    rewind(temp_file);
    char output[256];
    size_t bytes_read = fread(output, 1, sizeof(output) - 1, temp_file);
    output[bytes_read] = '\0';
    fclose(temp_file);

    TEST_ASSERT_EQUAL_INT(0, result);
    TEST_ASSERT_EQUAL_STRING("123\n", output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_print_number_negative_num_digits_all_nonzero);
    return UNITY_END();
}

